        }
        const uint8_t a = base64_value(s[i]);
        const uint8_t b = base64_value(s[i + 1]);
        const uint8_t c = base64_value(s[i + 2]);
        const uint8_t d = base64_value(s[i + 3]);
        if (a > 63 || b > 63) {
